SELECT * FROM lease_item_vat_invoice WHERE deleted = '0'
AND invoice_payer_name LIKE CONCAT('%', #{req.invoicePayerName}, '%')
AND invoice_seller_name LIKE CONCAT('%', #{req.invoiceSellerName}, '%')
AND status = #{req.status}
AND lease_item_info_id = #{req.leaseholdId}
AND invoice_issue_date BETWEEN #{req.invoiceIssueDateFrom} AND #{req.invoiceIssueDateTo}
AND verify_result IN ('VERIFICATION_PASSED', 'VERIFICATION_NOT_PASSED', 'CHECK_FAILURE','VERIFICATION_FAILED')
AND verify_result = #{req.verifyResult}
ORDER BY CASE WHEN note IS NOT NULL THEN create_time ELSE 1 END DESC, create_time DESC
